css:
.rm-t-my-mvxi0bil-c18e{padding:48px 56px;background:#ffffff;color:#1f2937;font-size:13.5px;line-height:1.62;}
.rm-t-my-mvxi0bil-c18e{display:grid;grid-template-columns:268px minmax(0,1fr);padding:0;align-items:start;grid-auto-flow:row dense;background:linear-gradient(90deg,#254665 0 268px,#ffffff 268px);}
.rm-t-my-mvxi0bil-c18e .rm-head{display:block;grid-column:1;grid-row:1;align-self:start;padding:48px 24px 54px;background:#254665;color:#ffffff;}
.rm-t-my-mvxi0bil-c18e .rm-head .rm-name{color:#ffffff;font-size:26px;letter-spacing:.02em;}
.rm-t-my-mvxi0bil-c18e .rm-head .rm-role{color:rgba(255,255,255,0.84);letter-spacing:.06em;}
.rm-t-my-mvxi0bil-c18e .rm-head .rm-contact{grid-template-columns:minmax(0,1fr);gap:7px;margin:16px 0 0;}
.rm-t-my-mvxi0bil-c18e .rm-head .rm-contact .rm-k{color:rgba(255,255,255,0.6);}
.rm-t-my-mvxi0bil-c18e .rm-head .rm-contact .rm-v{color:#ffffff;}
.rm-t-my-mvxi0bil-c18e .rm-head .rm-photo{width:84px;height:84px;margin:0 auto 18px;}
.rm-t-my-mvxi0bil-c18e .rm-body{display:contents;}
.rm-t-my-mvxi0bil-c18e .rm-sec-summary,.rm-t-my-mvxi0bil-c18e .rm-sec-experience,.rm-t-my-mvxi0bil-c18e .rm-sec-projects,.rm-t-my-mvxi0bil-c18e .rm-sec-education,.rm-t-my-mvxi0bil-c18e .rm-sec-awards{grid-column:2;grid-row:auto;align-self:start;padding-left:56px;padding-right:56px;}
.rm-t-my-mvxi0bil-c18e .rm-sec-summary:first-of-type{padding-top:48px;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills{grid-column:1;grid-row:auto;align-self:start;padding:0 24px;margin-top:18px;color:#ffffff;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills:first-of-type{margin-top:0;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-sec-h{border-bottom:1px solid rgba(255,255,255,0.34);}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-sec-t{color:#ffffff;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-sec-h::before{background:rgba(255,255,255,0.92);}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-summary,.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-para,.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-v,.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-item-t{color:#ffffff;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-item-role,.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-date{color:rgba(255,255,255,0.8);}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-k,.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-skill-k{color:rgba(255,255,255,0.72);}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-tag{border:1px solid rgba(255,255,255,0.45);background:rgba(255,255,255,0.1);color:#ffffff;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-bullets li::marker{color:rgba(255,255,255,0.8);}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-skill-row{display:block;margin:0 0 8px;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-skill-k{display:block;margin:0 0 3px;letter-spacing:.08em;}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-edu-courses{color:rgba(255,255,255,0.78);}
.rm-t-my-mvxi0bil-c18e .rm-sec-skills .rm-bullets{padding-left:16px;}
.rm-t-my-mvxi0bil-c18e .rm-name{color:#3c2418;font-size:32px;font-weight:700;letter-spacing:.04em;}
.rm-t-my-mvxi0bil-c18e .rm-role{color:#2b3e52;font-size:14.58px;}
.rm-t-my-mvxi0bil-c18e .rm-contact{grid-template-columns:repeat(2,minmax(0,1fr));color:#1f2937;}
.rm-t-my-mvxi0bil-c18e .rm-c .rm-k{color:#7d838b;}
.rm-t-my-mvxi0bil-c18e .rm-v{color:#1f2937;}
.rm-t-my-mvxi0bil-c18e .rm-item-t{color:#3c2418;}
.rm-t-my-mvxi0bil-c18e .rm-item-role,.rm-t-my-mvxi0bil-c18e .rm-date{color:#31353f;}
.rm-t-my-mvxi0bil-c18e .rm-edu-courses .rm-k,.rm-t-my-mvxi0bil-c18e .rm-skill-k{color:#59453b;}
.rm-t-my-mvxi0bil-c18e .rm-sec{margin-top:18px;}
.rm-t-my-mvxi0bil-c18e .rm-sec-t{color:#3c2418;font-size:12.5px;font-weight:700;letter-spacing:.14em;}
.rm-t-my-mvxi0bil-c18e .rm-tag{border:1px solid rgba(37,70,101,0.34);background:rgba(37,70,101,0.06);color:#233d57;}
.rm-t-my-mvxi0bil-c18e .rm-bullets li::marker{color:#254665;}
.rm-t-my-mvxi0bil-c18e .rm-summary{color:#1f2937;}
.rm-t-my-mvxi0bil-c18e .rm-sec-h{position:relative;padding-left:34px;border-bottom:1px solid rgba(37,70,101,0.42);padding-bottom:3px;}
.rm-t-my-mvxi0bil-c18e .rm-sec-h::before{content:"";position:absolute;left:0;top:1px;width:22px;height:22px;border-radius:50%;background:#254665;}
